public sealed partial class BedTypeMap : Map<BedType, BedTypeModel>;

public sealed partial class BedMap : Map<Bed, BedModel>
{
    protected override void Configure(IMapBuilder<Bed, BedModel> map) => map
        // Not a column of its own: the state column read as a bed.
        .Member(m => m.BedState, e => (EnumBedState)e.State)
        // BedTypeMap's tree is written in here, with the null check added.
        .Member(m => m.BedType, e => e.BedType.To<BedTypeModel>())
        // Not loaded on this path, and saying so keeps it accounted for.
        .Ignore(m => m.BuildingUnit, m => m.Department);
}

// The pair is already in the base type, so the query says nothing about shape.
public sealed partial class BedQuery : Specification<Bed, BedModel>
{
    public BedQuery(short id) => Where(e => e.Id == id);
}
